(function () {
const K = 10;
const X0 = 60;
const X1 = 340;
const svg = document.getElementById("bench-art");

function rankScoreThousandths(rank) {
  return 1000 / (K + rank);
}

function fusedScoreThousandths(kwRank, vecRank) {
  return rankScoreThousandths(kwRank) + rankScoreThousandths(vecRank);
}

const MAX_FUSED = fusedScoreThousandths(1, 1);

function knobX(input) {
  const mn = Number(input.min);
  const mx = Number(input.max);
  return X0 + (Number(input.value) - mn) / (mx - mn) * (X1 - X0);
}

function update() {
  const kwIn = document.getElementById("kwrank");
  const vecIn = document.getElementById("vecrank");
  const kw = Number(kwIn.value);
  const vec = Number(vecIn.value);
  const a = rankScoreThousandths(kw);
  const b = rankScoreThousandths(vec);
  const f = fusedScoreThousandths(kw, vec);
  document.getElementById("kwscore").textContent = a.toFixed(1) + " thousandths";
  document.getElementById("vecscore").textContent = b.toFixed(1) + " thousandths";
  document.getElementById("fused").textContent = f.toFixed(1) + " thousandths";
  const kx = knobX(kwIn);
  const vx = knobX(vecIn);
  document.getElementById("kwknob").setAttribute("cx", kx);
  document.getElementById("vecknob").setAttribute("cx", vx);
  const kt = document.getElementById("kwtxt");
  const vt = document.getElementById("vectxt");
  kt.setAttribute("x", kx);
  vt.setAttribute("x", vx);
  kt.textContent = kw;
  vt.textContent = vec;
  document.getElementById("fusedbar").style.transform = "scaleX(" + (f / MAX_FUSED).toFixed(4) + ")";
  const msg = "Keyword rank " + kw + " and vector rank " + vec + " give a fused score of " + f.toFixed(1) + " thousandths";
  svg.setAttribute("aria-label", msg);
  document.getElementById("found").textContent = "Keyword rank " + kw + " gives " + a.toFixed(1) + ", vector rank " + vec + " gives " + b.toFixed(1) + ", so the fused score is " + f.toFixed(1) + " thousandths.";
}

function wire(id) {
  const input = document.getElementById(id);
  const h = svg.querySelector('[data-synapse-handle="' + id + '"]');
  let held = false;
  h.addEventListener("pointerdown", (e) => {
    held = true;
    h.setPointerCapture(e.pointerId);
    e.preventDefault();
  });
  h.addEventListener("pointermove", (e) => {
    if (!held) return;
    const r = svg.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width * 400;
    let f = (x - X0) / (X1 - X0);
    f = Math.max(0, Math.min(1, f));
    const mn = Number(input.min);
    const mx = Number(input.max);
    const st = Number(input.step);
    const v = mn + Math.round(f * (mx - mn) / st) * st;
    input.value = v;
    input.dispatchEvent(new Event("input", {bubbles: true}));
  });
  h.addEventListener("pointerup", () => { held = false; });
  h.addEventListener("pointercancel", () => { held = false; });
  input.addEventListener("input", update);
}

wire("kwrank");
wire("vecrank");
update();
})();</script></body></html>","citations":[{"source":"UNVERIFIED (no textbook page has been checked for this Environment)","page":null,"quote":null,"verified":false,"printedPage":null}],"checked":{"layers":["postprocess","scan","render","wording"],"controlsExercised":2,"gridPoints":0,"referenceCases":0,"readouts":3,"models":[],"limits":"Written whole by a model and not built on the Kit, so none of its numbers or formulas were compared with an audited science model. Code checked that it runs and that its controls work and a second model read its words and formulas, but only for a short, scripted stretch of time. No textbook source was checked and a person has not reviewed it. Check it against your textbook."},"planSummary":"A simple page written whole by a model, the last step when no fuller lab passed its checks (topic physics_form4_measurement)."}}
